"""Generate the browser's local catalog from the native definitions (no ROM art)."""
from pathlib import Path
import json
import re
ROOT = Path(__file__).resolve().parents[2]
source = (ROOT / 'port/achievements/local_achievements.c').read_text(encoding='utf-8')
rows = re.findall(r'\{("(?:[^"\\]|\\.)*"), ("(?:[^"\\]|\\.)*"), ("(?:[^"\\]|\\.)*"), ("(?:[^"\\]|\\.)*")\}', source)
assert len(rows) == 16
catalog = [list(map(json.loads, row)) for row in rows]
(ROOT / 'port/web/achievement-data.js').write_text(
    '// Generated by gen_web_achievements.py; shared native local challenges.\n'
    'window.ReKHLocalAchievements=' + json.dumps(catalog, ensure_ascii=False, separators=(',', ':')) + ';\n', encoding='utf-8')
